+static void merge_sort_iter(uint32_t* a, uint32_t* tmp, size_t n) {
+    size_t width = 1;
+    while (width < n) {
+        for (size_t i = 0; i < n; i += 2 * width) {
+            size_t lo = i;
+            size_t mid = std::min(i + width, n);
+            size_t hi = std::min(i + 2 * width, n);
+            size_t len = hi - lo;
